'use strict';

const $ = id => document.getElementById(id);
const state = {catalog:null,slots:[],assignments:[],free:[],consents:[],leads:[],site:null,collections:[],events:[],classId:'',programId:null,view:'home'};
const viewMeta = {
  home:['总览','工作台首页'],classes:['课堂管理','班级与学生'],courses:['教学内容','课程与课题'],
  reviews:['创作流程','作品审核'],delivery:['家长服务','家长交付'],leads:['招生运营','招生咨询'],site:['公开网站','网站内容'],
};

function toast(text, timeout=3600){const el=$('message');el.textContent=text;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,timeout);}
function payload(value){return{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(value)};}
async function api(path,options={}){
  const response=await fetch(path,{credentials:'same-origin',...options});
  if(response.status===401){window.location.replace('/teacher/');throw Error('登录已失效');}
  const kind=response.headers.get('content-type')||'';
  if(kind.startsWith('text/csv')||kind==='application/zip'){if(!response.ok)throw Error('文件下载失败');return response.blob();}
  const data=await response.json().catch(()=>{throw Error('暂时连不上教师服务，请检查网络后重试。');});
  if(!response.ok)throw Error(data.error||'操作失败');return data;
}
async function action(path,options={},success='操作已完成'){try{await api(path,{method:'POST',...options});await refresh();toast(success);}catch(error){toast(error.message);}}
function button(parent,label,click,kind='secondary'){const el=document.createElement('button');el.type='button';el.textContent=label;el.className=kind;el.onclick=click;parent.append(el);return el;}
function link(parent,label,href){const el=document.createElement('a');el.textContent=label;el.href=href;el.target='_blank';el.rel='noopener noreferrer';el.className='button secondary';parent.append(el);return el;}
function cell(row,value=''){const el=document.createElement('td');el.textContent=value;row.append(el);return el;}
function empty(host,text,columns=0){if(columns){const tr=document.createElement('tr'),td=cell(tr,text);td.colSpan=columns;host.append(tr);}else{const p=document.createElement('p');p.className='empty-state';p.textContent=text;host.append(p);}}
function statusChip(status){const span=document.createElement('span');span.className='status-chip '+(status==='待审核'?'pending':status==='已发布'?'published':status==='需修改'?'revise':'');span.textContent=status||'未提交';return span;}
function fillSelect(id,items,valueKey='id',textKey='title',placeholder='暂无可选项'){
  const el=$(id),keep=el.value;el.replaceChildren();
  if(!items.length){const option=document.createElement('option');option.value='';option.textContent=placeholder;el.append(option);return;}
  for(const item of items){const option=document.createElement('option');option.value=item[valueKey];option.textContent=item[textKey];el.append(option);}
  if(items.some(item=>String(item[valueKey])===keep))el.value=keep;
}
function currentAssignments(){return state.assignments.filter(item=>item.class_id===state.classId);}
function currentFree(){return state.free.filter(item=>item.code.startsWith(state.classId+'-'));}
function allPublished(){return [...state.assignments.filter(x=>x.published_at).map(x=>({...x,workKind:'course',workTitle:x.lesson_title,workId:x.lesson_id})),...state.free.filter(x=>x.published_submission_id).map(x=>({...x,workKind:'free',workTitle:x.title,workId:x.id}))];}

async function refresh(){
  try{
    const values=await Promise.all(['/api/admin/catalog','/api/admin/assignments','/api/admin/slots','/api/admin/independent','/api/admin/consents','/api/admin/consultations','/api/admin/site-content','/api/admin/collections','/api/admin/publication-events'].map(api));
    [state.catalog,state.assignments,state.slots,state.free,state.consents,state.leads,state.site,state.collections,state.events]=values;
    if(!state.catalog.classes.some(x=>x.class_id===state.classId))state.classId=state.catalog.classes[0]?.class_id||'';
    if(!state.catalog.programs.some(x=>x.id===state.programId))state.programId=state.catalog.programs[0]?.id||null;
    hydrateSelects();renderAll();
  }catch(error){toast(error.message,6000);}
}
function hydrateSelects(){
  const classes=state.catalog.classes;fillSelect('filter-class',classes,'class_id','class_id','尚未创建班级');$('filter-class').value=state.classId;
  for(const id of ['lesson-program','enroll-program','enroll-student-program','marketing-program'])fillSelect(id,state.catalog.programs);
  fillSelect('collection-program',state.catalog.programs.filter(x=>x.kind==='camp'));
  const lessonOptions=[{id:'',title:'全部课题'},...state.catalog.lessons];fillSelect('lesson-filter',lessonOptions);
  fillSelect('enroll-student',state.slots.filter(x=>x.class_id===state.classId),'code','code','当前班级暂无学生');
  const categories=[{category:'',title:'全部类别'},...[...new Set(currentFree().map(x=>x.category))].map(category=>({category,title:category}))];fillSelect('free-filter',categories,'category','title');
  renderCollectionStudents();
}
function renderAll(){renderHome();renderClasses();renderCourses();renderReviews();renderDelivery();renderLeads();renderSite();updateBadges();}

function renderHome(){
  const assignments=currentAssignments(),free=currentFree(),works=[...assignments,...free];
  const pending=works.filter(x=>x.status==='待审核').length,newLeads=state.leads.filter(x=>x.status==='新咨询').length;
  const shared=allPublished().filter(x=>x.url&&!x.listed).length,published=allPublished().length;
  $('home-subtitle').textContent=state.classId?`正在查看 ${state.classId}，共有 ${assignments.length} 项课题任务。`:'先创建一个班级，开始安排课程。';
  const now=new Date();$('today-week').textContent=['星期日','星期一','星期二','星期三','星期四','星期五','星期六'][now.getDay()];$('today-date').textContent=`${now.getMonth()+1} 月 ${now.getDate()} 日`;
  const cards=[['待审核作品',pending,'优先处理','#fff2dc'],['新咨询',newLeads,'及时跟进','#ffe9e8'],['分享中未公开',shared,'家长可查看','#edf1ff'],['已发布作品',published,'累计成果','#e6f6ef']];
  const grid=$('kpi-grid');grid.replaceChildren();for(const [label,value,note,tone] of cards){const card=document.createElement('article');card.className='kpi-card';card.style.setProperty('--tone',tone);card.innerHTML=`<span class="kpi-label">${label}</span><strong class="kpi-value">${value}</strong><span class="kpi-note">${note}</span>`;grid.append(card);}
  const todo=$('todo-list');todo.replaceChildren();const missingConsent=allPublished().filter(x=>x.url&&!x.listed&&!activeConsent(x)).length;
  const todos=[[pending,'份作品等待审核','reviews','✓'],[newLeads,'条新咨询尚未联系','leads','↗'],[missingConsent,'份作品可登记公开同意','delivery','◇']];
  for(const [count,label,view,icon] of todos.filter(x=>x[0]>0)){const row=document.createElement('div');row.className='todo-item';row.innerHTML=`<span class="todo-icon">${icon}</span><span><strong>${count}${label}</strong><small>点击进入对应模块处理</small></span>`;button(row,'去处理',()=>switchView(view),'text-button');todo.append(row);}if(!todo.children.length)empty(todo,'今天没有紧急待办，可以检查课程准备和网站内容。');
  const statuses=['未提交','待审核','需修改','已发布'],colors=['#9aa5b5','#d88d24','#c4484d','#20856b'],counts=statuses.map(name=>works.filter(x=>(x.status||'未提交')===name).length),max=Math.max(...counts,1);$('work-total').textContent=`${works.length} 项`;
  const chart=$('work-chart');chart.replaceChildren();statuses.forEach((name,i)=>{const row=document.createElement('div');row.className='bar-row';row.innerHTML=`<span>${name}</span><div class="bar-track"><div class="bar-fill" style="width:${counts[i]/max*100}%;--bar:${colors[i]}"></div></div><strong>${counts[i]}</strong>`;chart.append(row);});
  const funnel=$('lead-funnel');funnel.replaceChildren();const leadStates=['新咨询','已联系','已约体验','已报名'];leadStates.forEach((name,i)=>{const count=state.leads.filter(x=>x.status===name).length,row=document.createElement('div');row.className='funnel-row';row.style.width=`${100-i*13}%`;row.style.opacity=String(1-i*.12);row.textContent=`${name} ${count}`;funnel.append(row);});
  const recent=$('recent-events');recent.replaceChildren();for(const item of state.events.filter(x=>!state.classId||x.code.startsWith(state.classId+'-')).slice(0,5)){const row=document.createElement('div');row.className='timeline-item';row.innerHTML=`<time>${item.created_at.slice(5,16).replace('T',' ')}</time><strong>${item.title}</strong><small>${item.code} · ${item.action}</small>`;recent.append(row);}if(!recent.children.length)empty(recent,'当前班级还没有发布或回退记录。');
}

function renderClasses(){
  $('class-count').textContent=`${state.catalog.classes.length} 个`;const list=$('class-list');list.replaceChildren();
  for(const item of state.catalog.classes){const btn=document.createElement('button');btn.className='selection-item'+(item.class_id===state.classId?' active':'');btn.innerHTML=`<span><strong>${item.class_id}</strong><small>${item.student_count} 名学生</small></span><span>›</span>`;btn.onclick=()=>selectClass(item.class_id);list.append(btn);}if(!list.children.length)empty(list,'还没有班级，请先创建。');
  $('students-title').textContent=state.classId?`${state.classId} · 学生账号`:'学生账号';const rows=$('student-rows');rows.replaceChildren();const students=state.slots.filter(x=>x.class_id===state.classId);
  for(const student of students){const tr=document.createElement('tr');cell(tr,student.code);const assigned=[...new Set(currentAssignments().filter(x=>x.code===student.code).map(x=>x.program_id))].length;cell(tr,String(assigned));const work=currentAssignments().filter(x=>x.code===student.code),published=work.filter(x=>x.published_at).length;cell(tr,`${published}/${work.length} 已发布`);rows.append(tr);}if(!students.length)empty(rows,'当前班级没有学生。',3);
}
function selectClass(classId){state.classId=classId;$('filter-class').value=classId;hydrateSelects();renderAll();toast(`已切换到 ${classId}`);}

function renderCourses(){
  $('course-count').textContent=`${state.catalog.programs.length} 门`;const list=$('course-list');list.replaceChildren();
  for(const item of state.catalog.programs){const btn=document.createElement('button');btn.className='selection-item'+(item.id===state.programId?' active':'');const status=item.marketing_status==='consulting'?'开放咨询':item.marketing_status==='paused'?'暂停咨询':item.marketing_status==='archived'?'已归档':'草稿';btn.innerHTML=`<span><strong>${item.title}</strong><small><i class="status-dot ${item.marketing_status==='draft'?'status-draft':item.marketing_status==='paused'?'status-paused':''}"></i>${status} · ${item.kind==='camp'?item.days+' 天营期':'半天课'}</small></span><span>›</span>`;btn.onclick=()=>{state.programId=item.id;renderCourses();};list.append(btn);}
  const host=$('course-detail');host.replaceChildren();const program=state.catalog.programs.find(x=>x.id===state.programId);if(!program)return empty(host,'请选择一门课程。');
  const enrolled=state.catalog.enrollments.filter(x=>x.program_id===program.id).reduce((sum,x)=>sum+x.student_count,0);const header=document.createElement('div');header.className='course-summary';header.innerHTML=`<div><span class="eyebrow">${program.slug}</span><h3>${program.title}</h3><p class="muted">${program.description||'尚未填写课程说明'}</p><div class="course-meta"><span>${program.kind==='camp'?program.days+' 天创作营':'半天课'}</span><span>${enrolled} 名学生已分配</span><span>${program.marketing_status==='consulting'?'公开咨询中':'未开放咨询'}</span></div></div>`;host.append(header);
  const heading=document.createElement('div');heading.className='panel-head';heading.innerHTML='<div><h3>课题与起始包</h3><p class="muted">起始包只支持静态网页 ZIP。</p></div>';button(heading,'＋ 添加课题',()=>openLessonDialog(program.id),'secondary');host.append(heading);
  const lessonList=document.createElement('div');lessonList.className='lesson-list';for(const lesson of state.catalog.lessons.filter(x=>x.program_id===program.id)){const row=document.createElement('div');row.className='lesson-row';const info=document.createElement('div');info.innerHTML=`<strong>第 ${lesson.day_no} 天 · ${lesson.title}</strong><small>${lesson.slug} · ${lesson.starter_available?'起始包已准备':'尚无起始包'}</small>`;row.append(info);if(lesson.format==='web'){const actions=document.createElement('div');actions.className='actions';const picker=document.createElement('input');picker.className='file-inline';picker.type='file';picker.accept='.zip,application/zip';picker.setAttribute('aria-label',`给 ${lesson.title} 选择起始包`);actions.append(picker);button(actions,'上传',async()=>{if(!picker.files[0])return toast('请先选择 ZIP 起始包');try{await api(`/api/admin/lessons/${lesson.id}/starter`,{method:'POST',headers:{'Content-Type':'application/zip'},body:picker.files[0]});await refresh();toast('起始包已更新');}catch(error){toast(error.message);}},'secondary');row.append(actions);}lessonList.append(row);}if(!lessonList.children.length)empty(lessonList,'这门课程还没有课题。');host.append(lessonList);
}

function renderReviews(){renderCourseReviews();renderFreeReviews();}
function renderCourseReviews(){const host=$('rows');host.replaceChildren();const status=$('review-filter').value,lesson=$('lesson-filter').value;const items=currentAssignments().filter(x=>(!status||(x.status||'未提交')===status)&&(!lesson||String(x.lesson_id)===lesson));for(const item of items){const tr=document.createElement('tr');const identity=cell(tr,`${item.code}\n${item.program_title} · 第 ${item.day_no} 天\n${item.lesson_title}`);identity.style.whiteSpace='pre-line';const stateCell=cell(tr);stateCell.append(statusChip(item.status));if(item.error){const p=document.createElement('p');p.className='muted';p.textContent=item.error;stateCell.append(p);}const actions=cell(tr);const wrap=document.createElement('div');wrap.className='actions';button(wrap,'版本',()=>showVersions(item.code,'course',item.lesson_id),'secondary');if(item.status==='待审核'){if(item.preview_url)link(wrap,'预览',item.preview_url);button(wrap,'确认发布',async()=>{if(confirm(`已检查 ${item.code} 的《${item.lesson_title}》，确认发布？`))await action(`/api/admin/publish/${item.submission_id}`,{},'作品已发布');},'primary');button(wrap,'退回修改',()=>reject(item),'secondary');}actions.append(wrap);host.append(tr);}if(!items.length)empty(host,'没有符合当前筛选条件的课内作品。',3);}
function renderFreeReviews(){const host=$('free-rows');host.replaceChildren();const category=$('free-filter').value,items=currentFree().filter(x=>!category||x.category===category);for(const item of items){const tr=document.createElement('tr');const identity=cell(tr,`${item.code}\n${item.title}\n${item.category} · ${item.summary}`);identity.style.whiteSpace='pre-line';const stateCell=cell(tr);stateCell.append(statusChip(item.status||'尚未上传'));if(item.error){const p=document.createElement('p');p.className='muted';p.textContent=item.error;stateCell.append(p);}const actions=cell(tr),wrap=document.createElement('div');wrap.className='actions';button(wrap,'版本',()=>showVersions(item.code,'independent',item.id),'secondary');if(item.status==='待审核'){if(item.preview_url)link(wrap,'预览',item.preview_url);button(wrap,'确认发布',async()=>{if(confirm(`已检查 ${item.code} 的《${item.title}》，确认发布？`))await action(`/api/admin/publish/${item.submission_id}`,{},'作品已发布');},'primary');button(wrap,'退回修改',()=>reject(item),'secondary');}actions.append(wrap);host.append(tr);}if(!items.length)empty(host,'当前班级还没有自由创作作品。',3);}
function reject(item){const reason=prompt('告诉孩子需要修改什么：');if(!reason?.trim())return;action(`/api/admin/reject/${item.submission_id}`,payload({reason:reason.trim()}),'已退回并记录修改建议');}

function activeConsent(item){return state.consents.find(x=>x.code===item.code&&!x.revoked_at&&((item.workKind==='free'&&x.independent_id===item.workId)||(item.workKind!=='free'&&x.lesson_id===item.workId)));}
function renderDelivery(){
  const host=$('delivery-rows'),filter=$('delivery-filter').value;host.replaceChildren();let works=allPublished().filter(x=>!state.classId||x.code.startsWith(state.classId+'-'));if(filter==='shared')works=works.filter(x=>x.url);if(filter==='revoked')works=works.filter(x=>!x.url);if(filter==='listed')works=works.filter(x=>x.listed);
  for(const item of works){const tr=document.createElement('tr');const name=cell(tr,`${item.code}\n${item.workTitle}`);name.style.whiteSpace='pre-line';const share=cell(tr,item.url?'链接有效':'分享已撤销');if(item.url){const small=document.createElement('small');small.className='muted';small.textContent=' 家长可持链接查看';share.append(small);}const consent=activeConsent(item);const publicCell=cell(tr,item.listed?'已在作品展':consent?'已同意、未公开':'尚未登记同意');const actions=cell(tr),wrap=document.createElement('div');wrap.className='actions';if(item.url){link(wrap,'打开',item.url);button(wrap,'复制链接',()=>copy(item.url),'secondary');button(wrap,'二维码',()=>showQr(item.qr,item.url),'secondary');button(wrap,'登记同意',()=>openConsent(item.code,item.workKind==='course'?item.workId:null,item.workKind==='free'?item.workId:null,item.workTitle),'secondary');}button(wrap,item.url?'撤销分享':'重建分享',async()=>{if(item.url&&!confirm('撤销后原链接和二维码会立即失效，确定继续？'))return;const path=item.workKind==='course'?`/api/admin/course/${item.workId}/share`:`/api/admin/independent/${item.workId}/share`;const body=item.workKind==='course'?{code:item.code,active:!item.url}:{active:!item.url};await action(path,payload(body),item.url?'分享已撤销':'分享链接已重新生成');},'secondary');button(wrap,item.listed?'移出作品展':'加入作品展',()=>toggleVisibility(item),'secondary');actions.append(wrap);host.append(tr);}if(!works.length)empty(host,'当前没有符合筛选条件的已发布作品。',4);
  renderCollections();renderConsents();
}
function toggleVisibility(item){const path=item.workKind==='course'?`/api/admin/visibility/${item.code}/${item.workId}`:`/api/admin/independent/${item.workId}/visibility`;action(path,payload({listed:!item.listed}),item.listed?'已从作品展移除':'已加入作品展');}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('链接已复制');}catch{toast('复制失败，请打开链接后手动复制');}}
function renderCollectionStudents(){const programId=Number($('collection-program').value),codes=[...new Set(state.assignments.filter(x=>x.program_id===programId&&x.class_id===state.classId).map(x=>x.code))];fillSelect('collection-student',codes.map(code=>({code})),'code','code','该营期暂无学生');}
function renderCollections(){renderCollectionStudents();const host=$('collection-list');host.replaceChildren();for(const item of state.collections.filter(x=>!state.classId||x.code.startsWith(state.classId+'-'))){const row=document.createElement('div');row.className='record-row';const info=document.createElement('div');info.innerHTML=`<strong>${item.code} · ${item.program_title}</strong><small>${item.active?'链接有效':'链接已撤销'}</small>`;row.append(info);const actions=document.createElement('div');actions.className='actions';if(item.url){link(actions,'打开',item.url);button(actions,'复制',()=>copy(item.url),'secondary');}button(actions,item.active?'撤销':'重新生成',async()=>{if(item.active&&!confirm('撤销后旧作品集链接会失效，确定继续？'))return;await action('/api/admin/collections',payload({code:item.code,program_id:item.program_id,active:!item.active}));},'secondary');row.append(actions);host.append(row);}if(!host.children.length)empty(host,'当前班级还没有营期作品集。');}
function renderConsents(){const host=$('consent-list');host.replaceChildren();for(const item of state.consents.filter(x=>!state.classId||x.code.startsWith(state.classId+'-'))){const row=document.createElement('div');row.className='record-row';const info=document.createElement('div');info.innerHTML=`<strong>${item.code} · ${item.lesson_id?'课题 '+item.lesson_id:'自由作品 '+item.independent_id}</strong><small>${item.guardian_ref} · ${item.consent_at} · ${item.channel}${item.revoked_at?' · 已撤回':''}<br>凭据：${item.evidence_ref}</small>`;row.append(info);if(!item.revoked_at)button(row,'登记撤回',async()=>{if(confirm('确认家长已撤回公开展示同意？作品会从公开展移除。'))await action(`/api/admin/consents/${item.id}/revoke`,{},'同意记录已撤回');},'secondary');host.append(row);}if(!host.children.length)empty(host,'当前班级尚无公开展示同意记录。');}

function renderLeads(){
  const statuses=['新咨询','已联系','已约体验','已报名','暂不跟进'];const summary=$('lead-summary');summary.replaceChildren();for(const status of statuses){const card=document.createElement('div');card.className='mini-stat';card.innerHTML=`<strong>${state.leads.filter(x=>x.status===status).length}</strong><span>${status}</span>`;summary.append(card);}
  const host=$('lead-rows'),filter=$('lead-filter').value,source=$('source-filter').value;host.replaceChildren();const select=$('source-filter');select.replaceChildren();const all=document.createElement('option');all.value='';all.textContent='全部来源';select.append(all);for(const value of [...new Set(state.leads.map(x=>x.source||'直接访问'))].sort()){const option=document.createElement('option');option.value=value;option.textContent=value;select.append(option);}select.value=source;
  const items=state.leads.filter(x=>(!filter||x.status===filter)&&(!source||(x.source||'直接访问')===source));for(const item of items){const tr=document.createElement('tr');const where=cell(tr,`${item.created_at.slice(0,16).replace('T',' ')}\n${item.source||'直接访问'}\n${item.entry_path}`);where.style.whiteSpace='pre-line';const detail=cell(tr,`${item.parent_name} · ${item.contact_kind} ${item.contact}\n孩子年龄：${item.child_age}\n感兴趣：${item.interest}${item.message?'\n留言：'+item.message:''}`);detail.style.whiteSpace='pre-line';const follow=cell(tr),status=document.createElement('select');for(const value of statuses){const option=document.createElement('option');option.value=value;option.textContent=value;status.append(option);}status.value=item.status;status.setAttribute('aria-label',`${item.parent_name} 的跟进状态`);const note=document.createElement('input');note.value=item.note;note.maxLength=500;note.placeholder='跟进备注';follow.append(status,note);button(follow,'保存跟进',()=>action(`/api/admin/consultations/${item.id}`,payload({status:status.value,note:note.value.trim()}),'咨询状态已保存'),'secondary');button(follow,'删除',async()=>{if(confirm(`确定删除 ${item.parent_name} 的咨询记录？此操作不能恢复。`))await action(`/api/admin/consultations/${item.id}/delete`,{},'咨询记录已删除');},'text-button');host.append(tr);}if(!items.length)empty(host,'当前没有符合筛选条件的咨询。',3);
}

function renderSite(){if(!state.site)return;const marketing=$('marketing-program');if(state.programId)marketing.value=String(state.programId);renderMarketing();$('teacher-intro').value=state.site.teacher_intro||'';$('demo-title').value=state.site.demo_title||'';$('demo-summary').value=state.site.demo_summary||'';const faq=$('faq-editor');faq.replaceChildren();for(const item of state.site.faqs||[])faqRow(item.q,item.a);$('wechat-qr-preview').hidden=!state.site.wechat_qr_available;if(state.site.wechat_qr_available)$('wechat-qr-preview').src='/api/public/wechat-qr?v='+Date.now();}
function renderMarketing(){const program=state.catalog.programs.find(x=>String(x.id)===$('marketing-program').value);if(!program)return;$('marketing-status').value=program.marketing_status||'draft';for(const name of ['summary','audience','outcome','duration','parent_role'])$('marketing-'+name.replace('_','-')).value=program['marketing_'+name]||'';$('marketing-preview').href=`https://codexai.site/courses/${program.slug==='workshop01'?'money':program.slug}/`;$('marketing-preview').hidden=['draft','archived'].includes(program.marketing_status);}
function faqRow(q='',a=''){const row=document.createElement('div');row.className='faq-row';const question=document.createElement('label');question.textContent='问题';const qi=document.createElement('input');qi.className='faq-question';qi.value=q;qi.maxLength=160;question.append(qi);const answer=document.createElement('label');answer.textContent='回答';const ai=document.createElement('textarea');ai.className='faq-answer';ai.value=a;ai.maxLength=600;ai.rows=2;answer.append(ai);row.append(question,answer);button(row,'删除',()=>row.remove(),'secondary');$('faq-editor').append(row);}

async function showVersions(code,kind,id){try{const versions=await api(`/api/admin/versions?code=${encodeURIComponent(code)}&kind=${kind}&id=${id}`),host=$('versions-list');host.replaceChildren();for(const version of versions){const row=document.createElement('div');row.className='record-row';const info=document.createElement('div');info.innerHTML=`<strong>版本 #${version.id} · ${version.status}</strong><small>${version.received_at}${version.error?' · '+version.error:''}</small>`;row.append(info);const actions=document.createElement('div');actions.className='actions';if(version.preview_url)link(actions,'预览',version.preview_url);if(version.status==='已发布')button(actions,'回退到此版',async()=>{if(confirm(`把 ${code} 的家长作品回退到版本 #${version.id}？公开作品展会先下架。`)){await action(`/api/admin/rollback/${version.id}`,{},`已回退到版本 #${version.id}`);$('versions-dialog').close();}},'secondary');row.append(actions);host.append(row);}if(!versions.length)empty(host,'暂无历史版本。');$('versions-dialog').showModal();}catch(error){toast(error.message);}}
function openConsent(code,lessonId,freeId,title){$('consent-code').value=code;$('consent-lesson').value=lessonId||'';$('consent-free').value=freeId||'';$('consent-work').textContent=`${code} · ${title}`;$('consent-date').value=new Date().toISOString().slice(0,10);$('consent-dialog').showModal();}
function showQr(qr,url){$('qr-image').src=qr;$('qr-link').textContent=url;$('qr-dialog').showModal();}
function openLessonDialog(programId){$('lesson-program').value=String(programId);$('create-lesson-dialog').showModal();}
function switchView(view){state.view=view;document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.dataset.viewPanel===view));document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===view));$('page-kicker').textContent=viewMeta[view][0];$('page-title').textContent=viewMeta[view][1];$('class-switcher-wrap').hidden=['leads','site'].includes(view);$('sidebar').classList.remove('open');$('sidebar-scrim').hidden=true;history.replaceState(null,'','#'+view);window.scrollTo({top:0,behavior:'smooth'});}
function updateBadges(){const pending=[...state.assignments,...state.free].filter(x=>x.status==='待审核').length,newLeads=state.leads.filter(x=>x.status==='新咨询').length;for(const [id,value] of [['review-badge',pending],['lead-badge',newLeads]]){const el=$(id);el.textContent=value;el.hidden=!value;}}

document.querySelectorAll('.nav-item').forEach(button=>button.onclick=()=>switchView(button.dataset.view));
document.querySelectorAll('[data-go]').forEach(button=>button.onclick=()=>switchView(button.dataset.go));
document.querySelectorAll('[data-dialog]').forEach(button=>button.onclick=()=>$(button.dataset.dialog).showModal());
$('menu-toggle').onclick=()=>{$('sidebar').classList.add('open');$('sidebar-scrim').hidden=false;};$('sidebar-scrim').onclick=()=>{$('sidebar').classList.remove('open');$('sidebar-scrim').hidden=true;};
$('filter-class').onchange=()=>selectClass($('filter-class').value);$('refresh').onclick=()=>refresh().then(()=>toast('数据已刷新'));
$('logout').onclick=async()=>{await fetch('/api/admin/logout',{method:'POST',credentials:'same-origin'});window.location.replace('/teacher/');};
$('create-class').onclick=async()=>{const class_id=$('class-id').value.trim().toLowerCase(),count=Number($('count').value);if(!confirm(`创建 ${count} 个学生账号？`))return;try{await api('/api/admin/classes',payload({class_id,count}));state.classId=class_id;$('create-class-dialog').close();await refresh();switchView('classes');toast('班级已创建，请下载账号名单。');}catch(error){toast(error.message);}};
$('create-program').onclick=async()=>{const value={title:$('program-title').value.trim(),slug:$('program-slug').value.trim().toLowerCase(),kind:$('program-kind').value,days:Number($('program-days').value),description:$('program-description').value.trim()};try{const result=await api('/api/admin/programs',payload(value));state.programId=result.id;$('create-program-dialog').close();await refresh();switchView('courses');toast('课程已创建，请继续添加课题。');}catch(error){toast(error.message);}};
$('create-lesson').onclick=async()=>{const value={program_id:Number($('lesson-program').value),title:$('lesson-title').value.trim(),slug:$('lesson-slug').value.trim().toLowerCase(),day_no:Number($('lesson-day').value)};try{await api('/api/admin/lessons',payload(value));state.programId=value.program_id;$('create-lesson-dialog').close();await refresh();switchView('courses');toast('课题已添加，请上传起始包。');}catch(error){toast(error.message);}};
$('enroll').onclick=()=>{if(!state.classId)return toast('请先创建班级');action('/api/admin/enroll-class',payload({class_id:state.classId,program_id:Number($('enroll-program').value)}),'课程已分配给全班');};
$('assign-student').onclick=()=>{const code=$('enroll-student').value;if(!code)return toast('请先选择学生');action('/api/admin/enroll-student',payload({code,program_id:Number($('enroll-student-program').value)}),`课程已分配给 ${code}`);};
$('csv').onclick=async()=>{if(!state.classId)return toast('请先选择班级');try{const blob=await api('/api/admin/roster.csv?class_id='+encodeURIComponent(state.classId)),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=state.classId+'-账号名单.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){toast(error.message);}};
document.querySelectorAll('[data-review-tab]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-review-tab]').forEach(x=>x.classList.toggle('active',x===button));$('course-review-panel').hidden=button.dataset.reviewTab!=='course';$('free-review-panel').hidden=button.dataset.reviewTab!=='free';});
$('review-filter').onchange=renderCourseReviews;$('lesson-filter').onchange=renderCourseReviews;$('free-filter').onchange=renderFreeReviews;$('delivery-filter').onchange=renderDelivery;$('lead-filter').onchange=renderLeads;$('source-filter').onchange=renderLeads;$('marketing-program').onchange=()=>{state.programId=Number($('marketing-program').value);renderMarketing();};
$('collection-program').onchange=renderCollectionStudents;$('create-collection').onclick=async()=>{const code=$('collection-student').value,program_id=Number($('collection-program').value);if(!code||!program_id)return toast('请先选择已报名创作营的学生');await action('/api/admin/collections',payload({code,program_id,active:true}),'作品集已生成');};
$('export-leads').onclick=async()=>{try{const blob=await api('/api/admin/consultations.csv'),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='codexai-咨询线索.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){toast(error.message);}};
$('save-marketing').onclick=async()=>{const id=Number($('marketing-program').value);if(!id)return toast('请先选择课程');const value={status:$('marketing-status').value};for(const name of ['summary','audience','outcome','duration','parent_role'])value[name]=$('marketing-'+name.replace('_','-')).value.trim();await action(`/api/admin/programs/${id}/marketing`,payload(value),'课程对外信息已保存');};
$('add-faq').onclick=()=>faqRow();$('save-content').onclick=async()=>{const faqs=[...document.querySelectorAll('.faq-row')].map(row=>({q:row.querySelector('.faq-question').value.trim(),a:row.querySelector('.faq-answer').value.trim()}));const value={teacher_intro:$('teacher-intro').value.trim(),demo_title:$('demo-title').value.trim(),demo_summary:$('demo-summary').value.trim(),faqs};await action('/api/admin/site-content',payload(value),'网站内容已保存');};
$('upload-wechat-qr').onclick=async()=>{const file=$('wechat-qr-file').files[0];if(!file)return toast('请先选择真实的微信二维码图片');if(file.size>2000000)return toast('二维码图片不能超过 2MB');try{await api('/api/admin/wechat-qr',{method:'POST',headers:{'Content-Type':file.type},body:file});$('wechat-qr-file').value='';await refresh();toast('二维码已上传，请用手机扫码确认');}catch(error){toast(error.message);}};
$('save-consent').onclick=async()=>{const value={code:$('consent-code').value,lesson_id:$('consent-lesson').value?Number($('consent-lesson').value):null,independent_id:$('consent-free').value?Number($('consent-free').value):null,guardian_ref:$('guardian-ref').value.trim(),channel:$('consent-channel').value,consent_at:$('consent-date').value,evidence_ref:$('evidence-ref').value.trim()};try{await api('/api/admin/consents',payload(value));$('consent-dialog').close();$('guardian-ref').value='';$('evidence-ref').value='';await refresh();toast('家长同意已登记，现在可以加入作品展');}catch(error){toast(error.message);}};
$('cancel-consent').onclick=()=>$('consent-dialog').close();$('versions-close').onclick=()=>$('versions-dialog').close();$('qr-close').onclick=()=>$('qr-dialog').close();

switchView(location.hash.slice(1) in viewMeta?location.hash.slice(1):'home');
refresh();
